#!/usr/bin/env python3
"""
config_validator.py -- ZO-SENTINEL startup configuration validator.
Checks: write_service reachable, inference_router reachable, env vars, ports.
v1.0.0: write_raw bypass -- MiniMax chronic failure on this module.
"""
import os, logging, requests
from pathlib import Path

log = logging.getLogger(__name__)
WRITE_SERVICE  = "http://127.0.0.1:8772"
INFERENCE_URL  = "http://127.0.0.1:8773"
PROJECT_DIR    = Path("/home/workspace/zo_sentinel")

REQUIRED_VARS = ["MINIMAX_API_KEY"]
REQUIRED_PORTS = {
    "write_service": 8772,
    "inference_router": 8773,
    "approval_workflow": 8780,
    "registry_api": 8781,
}


def check_write_service() -> dict:
    try:
        r = requests.get(WRITE_SERVICE + "/health", timeout=3)
        return {"ok": r.status_code == 200, "detail": f"HTTP {r.status_code}"}
    except Exception as e:
        return {"ok": False, "detail": str(e)}


def check_inference_router() -> dict:
    try:
        r = requests.get(INFERENCE_URL + "/health", timeout=3)
        return {"ok": r.status_code in (200, 404), "detail": f"HTTP {r.status_code}"}
    except Exception as e:
        return {"ok": False, "detail": str(e)}


def check_env_vars() -> dict:
    missing = [v for v in REQUIRED_VARS if not os.environ.get(v)]
    return {"ok": len(missing) == 0, "missing": missing}


def check_project_dirs() -> dict:
    dirs = [PROJECT_DIR, PROJECT_DIR / "directives"]
    missing = [str(d) for d in dirs if not d.exists()]
    return {"ok": len(missing) == 0, "missing": missing}


def run_checks() -> dict:
    results = {
        "write_service": check_write_service(),
        "inference_router": check_inference_router(),
        "env_vars": check_env_vars(),
        "project_dirs": check_project_dirs(),
    }
    all_ok = all(v.get("ok") for v in results.values())
    return {"overall": "PASS" if all_ok else "FAIL", "checks": results}


def run():
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s: %(message)s")
    result = run_checks()
    log.info("Config validation: %s", result["overall"])
    for name, check in result["checks"].items():
        status = "PASS" if check.get("ok") else "FAIL"
        log.info("  [%s] %s: %s", status, name, check)
    return result


if __name__ == "__main__":
    run()
